:root {
  --ink: #0a0c0b;
  --sand: #d8c4a2;
  --sand-dim: #8f836d;
  --amber: #f5a742;
  --amber-hot: #ffc46b;
  --red: #ff3f30;
  --green: #b7e37a;
  --line: rgba(226, 210, 182, 0.22);
  --panel: rgba(8, 10, 9, 0.58);
  --hud: 'Rajdhani', 'DejaVu Sans', sans-serif;
  --display: 'Barlow Condensed', 'DejaVu Sans Condensed', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #080a09;
  color: #f0e8d8;
  font-family: var(--hud);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

#app { position: relative; width: 100vw; height: 100vh; overflow: hidden; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.hidden { display: none !important; }

/* =========================================================================
   MENU
   ========================================================================= */
#menu {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: grid;
  grid-template-columns: minmax(420px, 46%) 1fr minmax(240px, 20%);
  grid-template-rows: auto 1fr auto;
  padding: 0 3.2vw;
  background:
    linear-gradient(90deg, rgba(5,7,6,0.94) 0%, rgba(5,7,6,0.82) 27%, rgba(5,7,6,0.20) 58%, rgba(5,7,6,0.38) 100%),
    linear-gradient(0deg, rgba(5,7,6,0.92) 0%, rgba(5,7,6,0.08) 38%, rgba(5,7,6,0.55) 100%);
  transition: opacity .55s ease, filter .55s ease;
}
#menu.closing { opacity: 0; filter: blur(6px); pointer-events: none; }
.menu-vignette {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse at 62% 48%, transparent 0%, transparent 38%, rgba(3,4,4,0.55) 100%);
  mix-blend-mode: multiply;
}
.menu-grain {
  position: absolute; inset: -50%;
  pointer-events: none; opacity: .055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  animation: grain 1.2s steps(3) infinite;
}
@keyframes grain { 0%{transform:translate(0,0)} 33%{transform:translate(-2%,1%)} 66%{transform:translate(1%,-2%)} 100%{transform:translate(0,0)} }

.menu-top {
  grid-column: 1 / -1;
  display: flex; align-items: center; justify-content: space-between;
  padding: 26px 0 18px;
  border-bottom: 1px solid var(--line);
  font-family: var(--display);
  letter-spacing: .18em;
  font-size: 12px;
  color: var(--sand-dim);
  position: relative; z-index: 2;
}
.brand { display: flex; align-items: center; gap: 12px; color: var(--sand); font-weight: 600; }
.brand i { color: var(--amber); font-style: normal; }
.brand-mark {
  width: 18px; height: 18px; display: inline-block;
  border: 1px solid var(--amber);
  background: linear-gradient(135deg, var(--amber) 0 45%, transparent 45% 55%, var(--amber) 55% 100%);
  transform: rotate(45deg);
  box-shadow: 0 0 14px rgba(245,167,66,.25);
}
.menu-top-right { display: flex; align-items: center; gap: 26px; }
.classified {
  color: var(--red); border: 1px solid rgba(255,63,48,.5);
  padding: 3px 9px 2px; letter-spacing: .26em; font-weight: 600;
  background: rgba(255,63,48,.08);
}

.menu-left {
  grid-column: 1;
  align-self: center;
  padding: 3vh 0 0;
  position: relative; z-index: 2;
  animation: rise .9s cubic-bezier(.16,1,.3,1) both;
}
@keyframes rise { from { opacity: 0; transform: translateY(26px); } to { opacity: 1; transform: none; } }
.eyebrow {
  display: flex; align-items: center; gap: 10px;
  font-family: var(--display); font-size: 12px; font-weight: 600;
  letter-spacing: .34em; color: var(--amber); text-transform: uppercase;
}
.eyebrow span { width: 26px; height: 2px; background: var(--amber); box-shadow: 0 0 10px rgba(245,167,66,.5); }
h1 {
  font-family: var(--display);
  font-weight: 900;
  line-height: .79;
  letter-spacing: -.012em;
  margin: 2.2vh 0 2.4vh;
  text-transform: uppercase;
  text-shadow: 0 4px 40px rgba(0,0,0,.65);
}
h1 .thin {
  display: block;
  font-size: clamp(3.4rem, 5.2vw, 6.1rem);
  color: transparent;
  -webkit-text-stroke: 1px rgba(226,210,182,.62);
  letter-spacing: .06em;
  margin-left: .06em;
}
h1 .big {
  display: block;
  font-size: clamp(5rem, 9.2vw, 11.5rem);
  color: #f1e6d0;
  background: linear-gradient(180deg, #fff5df 0%, #d9c4a0 46%, #8f7c5e 100%);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 8px 30px rgba(0,0,0,.45));
}
.lede {
  max-width: 420px;
  color: #b8ab93;
  font-size: 15px; line-height: 1.55; font-weight: 500;
  letter-spacing: .04em;
  border-left: 2px solid rgba(245,167,66,.55);
  padding-left: 14px;
  margin-bottom: 2.4vh;
}
.mission-card {
  display: grid; gap: 7px;
  width: min(380px, 100%);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 11px 0;
  margin-bottom: 2.8vh;
}
.mission-row {
  display: flex; justify-content: space-between;
  font-family: var(--display); font-size: 12px; letter-spacing: .16em;
  color: var(--sand-dim);
}
.mission-row b { color: var(--sand); font-weight: 600; }
.mission-row .threat { color: var(--red); }
.play-btn {
  position: relative;
  width: min(340px, 100%);
  padding: 15px 22px 13px;
  background: linear-gradient(100deg, rgba(245,167,66,.98), rgba(224,137,42,.92));
  border: 0;
  color: #17120a;
  font-family: var(--display);
  text-align: left;
  cursor: pointer;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
  box-shadow: 0 12px 38px rgba(245,167,66,.16), inset 0 1px 0 rgba(255,255,255,.5);
  transition: transform .18s ease, box-shadow .18s ease, filter .18s ease;
}
.play-btn::after {
  content: '›'; position: absolute; right: 20px; top: 50%; transform: translateY(-50%);
  font-family: var(--display); font-size: 34px; font-weight: 400; color: #17120a; opacity: .55;
}
.play-btn span { display: block; font-size: 28px; font-weight: 800; letter-spacing: .18em; line-height: 1; }
.play-btn small { display: block; font-family: var(--hud); font-size: 10px; font-weight: 700; letter-spacing: .26em; opacity: .72; margin-top: 5px; }
.play-btn:hover { transform: translateY(-2px); filter: brightness(1.06); box-shadow: 0 18px 50px rgba(245,167,66,.28), inset 0 1px 0 rgba(255,255,255,.55); }
.play-btn:active { transform: translateY(0) scale(.995); }
.controls {
  display: flex; flex-wrap: wrap; gap: 14px 20px;
  margin-top: 2.2vh;
  font-family: var(--display); font-size: 11px; letter-spacing: .13em;
  color: var(--sand-dim);
}
.controls kbd {
  font-family: var(--hud); font-size: 10px; font-weight: 700; letter-spacing: .05em;
  border: 1px solid rgba(226,210,182,.3); background: rgba(226,210,182,.06);
  padding: 2px 5px 1px; margin-right: 4px; color: var(--sand);
}

.menu-right {
  grid-column: 3;
  align-self: center;
  position: relative; z-index: 2;
  padding-top: 2vh;
  animation: rise 1.1s .12s cubic-bezier(.16,1,.3,1) both;
}
.dossier-head {
  display: flex; justify-content: space-between; align-items: baseline;
  font-family: var(--display); font-size: 11px; letter-spacing: .2em;
  color: var(--sand-dim); border-bottom: 1px solid var(--line); padding-bottom: 8px;
}
.dossier-head b { color: var(--amber); font-weight: 600; }
.operator-card {
  position: relative; margin: 12px 0 16px; height: 176px; overflow: hidden;
  background:
    radial-gradient(circle at 50% 36%, rgba(245,167,66,.16), transparent 52%),
    linear-gradient(160deg, rgba(35,37,31,.8), rgba(8,10,9,.75));
  border: 1px solid var(--line);
  clip-path: polygon(0 0, 100% 0, 100% 100%, 14px 100%, 0 calc(100% - 14px));
}
.op-silhouette { position: absolute; inset: 0; filter: drop-shadow(0 0 20px rgba(245,167,66,.2)); }
.op-head { position: absolute; left: 50%; top: 28px; width: 32px; height: 38px; transform: translateX(-50%); border-radius: 44% 44% 38% 38%; background: linear-gradient(180deg, #6f634c, #2d2b23); }
.op-head::before { content:''; position:absolute; inset: 5px -6px auto; height: 15px; background:#191b17; border-radius: 7px 7px 3px 3px; }
.op-body { position: absolute; left: 50%; top: 63px; width: 86px; height: 92px; transform: translateX(-50%); background: linear-gradient(180deg, #4a4637, #1a1c17); clip-path: polygon(18% 0, 82% 0, 100% 24%, 92% 100%, 8% 100%, 0 24%); }
.op-rifle { position: absolute; left: 47%; top: 78px; width: 128px; height: 9px; transform: translateX(-50%) rotate(-16deg); background: #0e100e; box-shadow: 0 0 0 2px rgba(120,110,88,.25); }
.op-scan { position: absolute; left: 0; right: 0; top: 0; height: 28%; background: linear-gradient(180deg, transparent, rgba(245,167,66,.12), transparent); animation: scan 4s linear infinite; }
@keyframes scan { 0% { transform: translateY(-120%); } 100% { transform: translateY(460%); } }
.op-tag { position: absolute; bottom: 9px; left: 12px; font-family: var(--display); font-size: 10px; letter-spacing: .18em; color: var(--amber); }
.stat { margin: 9px 0; }
.stat div { display: flex; justify-content: space-between; font-family: var(--display); font-size: 10px; letter-spacing: .16em; color: var(--sand-dim); }
.stat b { color: var(--sand); font-weight: 600; }
.stat i { display: block; height: 2px; margin-top: 4px; background: rgba(226,210,182,.14); position: relative; }
