_buildOptic() {
  const g = this.group;

  addBeveled(g, 0.042, 0.018, 0.105, MAT.black, 0, 0.115, -0.1, 0, 0, 0, 0.003);
  addBeveled(g, 0.034, 0.028, 0.014, MAT.black, 0, 0.128, -0.058, 0, 0, 0, 0.002);
  addBeveled(g, 0.034, 0.028, 0.014, MAT.black, 0, 0.128, -0.142, 0, 0, 0, 0.002);

  addCylinder(g, 0.026, 0.026, 0.125, MAT.black, 0, 0.14, -0.1, 24, Math.PI / 2);
  addCylinder(g, 0.032, 0.03, 0.022, MAT.black, 0, 0.14, -0.032, 24, Math.PI / 2);
  addCylinder(g, 0.032, 0.034, 0.022, MAT.black, 0, 0.14, -0.168, 24, Math.PI / 2);
  addTorus(g, 0.0275, 0.0035, MAT.gunmetalDark, 0, 0.14, -0.057, 0, 0, 0);
  addTorus(g, 0.0275, 0.0035, MAT.gunmetalDark, 0, 0.14, -0.143, 0, 0, 0);

  // Lenses sit just inside each bell.
  const rearLens = place(g, new THREE.Mesh(new THREE.CircleGeometry(0.027, 28), MAT.lens), 0, 0.14, -0.024);
  const frontLens = place(g, new THREE.Mesh(new THREE.CircleGeometry(0.028, 28), MAT.lens), 0, 0.14, -0.176);
  rearLens.renderOrder = 2;
  frontLens.renderOrder = 2;

  // Elevation and windage turrets.
  addCylinder(g, 0.013, 0.013, 0.019, MAT.gunmetalDark, 0, 0.176, -0.1, 16);
  addCylinder(g, 0.014, 0.014, 0.005, MAT.steel, 0, 0.187, -0.1, 16);
  addCylinder(g, 0.012, 0.012, 0.019, MAT.gunmetalDark, 0.033, 0.14, -0.1, 16, 0, 0, Math.PI / 2);
  addCylinder(g, 0.013, 0.013, 0.005, MAT.steel, 0.044, 0.14, -0.1, 16, 0, 0, Math.PI / 2);
  addInstanced(
    g,
    new THREE.CylinderGeometry(0.0022, 0.0022, 0.005, 6),
    MAT.steel,
    [[-0.016, 0.126, -0.07, 0, 0, 0], [0.016, 0.126, -0.07, 0, 0, 0],
      [-0.016, 0.126, -0.13, 0, 0, 0], [0.016, 0.126, -0.13, 0, 0, 0]],
  );

  // Reticle: a bright core, a faint ring, and a tiny sphere for side-on visibility.
  const dot = place(g, new THREE.Mesh(new THREE.CircleGeometry(0.0018, 14), MAT.reticle), 0, 0.14, -0.092);
  const ring = place(g, new THREE.Mesh(new THREE.TorusGeometry(0.0065, 0.0007, 6, 24), MAT.reticleRing), 0, 0.14, -0.092);
  const core = place(g, new THREE.Mesh(new THREE.SphereGeometry(0.0018, 8, 6), MAT.reticle), 0, 0.14, -0.092);
  dot.renderOrder = 30;
  ring.renderOrder = 29;
  core.renderOrder = 30;
  this.reticle = dot;
}

