_createMuzzleLights() {
  if (!this.scene) return;
  for (let i = 0; i < 2; i++) {
    const light = new THREE.PointLight(0xffa04a, 0, 7, 2);
    light.name = 'enemyMuzzleLight';
    light.castShadow = false;
    this.scene.add(light);
    this._muzzleLights.push({ light, life: 0 });
  }
}

